ok("masks a Basic credential", redactSecrets("Basic dXNlcjpwYXNzd29yZA") === "Basic ***");
ok("masks a provider sk- key", (() => { const o = redactSecrets("key=sk-abcdef123456"); return o.includes("sk-***") && !o.includes("abcdef123456"); })());
